create role anon;create role authenticated;create role service_role;create schema auth;create table auth.users(id uuid primary key);create table public.sanji_members(user_id uuid primary key);create table public.sanji_records(id uuid primary key default gen_random_uuid(),owner uuid,kind text,data jsonb,version int default 1,updated timestamptz default now());create table public.sanji_suppression(owner uuid,identity text);create table public.sanji_connections(owner uuid,provider text,summary jsonb,encrypted text);create table public.sanji_daily_campaign_policy(owner uuid,revision int,snapshot_id uuid,data jsonb);create table public.sanji_daily_campaign_snapshots(owner uuid,id uuid,sha256 text,data jsonb);create table public.sanji_daily_campaign_queue(owner uuid,creator_key text);create table public.sanji_outbox(id uuid primary key default gen_random_uuid(),owner uuid,target uuid,channel text,fingerprint text unique,status text,data jsonb,created timestamptz default now());create function public.sanji_blocked(uuid,jsonb) returns boolean language sql as $$select coalesce($2->>'status' in ('거절','수신 거부'),false)$$;